if _fn then
    local _ok, _execErr = pcall(_fn)
    if not _ok then
        warn("[WDYM Engine Runtime Error]: " .. tostring(_execErr))
    end
else
    warn("[WDYM Engine Load Error]: " .. tostring(_err))
end
